def converter_categorias(apps, schema_editor):
    Produto = apps.get_model("produtos", "Produto")
    Categoria = apps.get_model("produtos", "Categoria")
    for produto in Produto.objects.all():
        nome = (produto.categoria_texto or "").strip()[:60]
        if not nome:
            continue
        categoria, _ = Categoria.objects.get_or_create(
            estabelecimento_id=produto.estabelecimento_id, nome=nome,
        )
        produto.categoria = categoria
        produto.save(update_fields=["categoria"])


